package dev.pocketengine.features.teams;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** Values only. The original TaskStore's private owner admission is separately exercised natively. */
public final class TeamParentRoundBudgetTest {
    private JSONObject source()throws Exception{return new JSONObject().put("nativeProjectWorkPlan",true).put("nativeProjectRoundReview","a".repeat(64)).put("includeParentInference",true).put("parentCoordinationScopeId","new-run").put("actualTeamRunIds",new JSONArray());}
    private JSONObject binding()throws Exception{return new JSONObject().put("teamRunId","").put("parentCoordinationScopeId","new-run").put("childTaskId","parent").put("childRunId","new-run").put("childEpoch",2).put("memberId","@parent").put("assignmentId","parent");}
    @Test public void legacyPoolAndOrdinaryEmptyTeamCannotClaimNewRoundAuthority()throws Exception{JSONObject legacy=TeamParentBudget.create("parent","new-run",4,4,new JSONObject());assertThrows(SecurityException.class,()->TeamParentBudget.reserve(legacy,binding(),"parent_coordination","call-original",1,0));assertEquals(0,legacy.getJSONArray("reservations").length());assertThrows(SecurityException.class,()->TeamParentBudget.create("parent","new-run",65,4,new JSONObject()));assertThrows(SecurityException.class,()->TeamParentBudget.create("parent","new-run",4,33,new JSONObject()));}
    @Test public void sameOriginalCallBeforeAndAfterTeamAssociationIsOneImmutableReservation()throws Exception{JSONObject nativeSource=source(),pool=TeamParentBudget.create("parent","new-run",5,5,nativeSource),first=TeamParentBudget.reserve(pool,binding(),"parent_coordination","call-original",1,0);pool.getJSONObject("budgetSource").getJSONArray("actualTeamRunIds").put("real-team-1");JSONObject again=TeamParentBudget.reserve(pool,binding(),"parent_coordination","call-original",1,0);assertSame(first,again);assertEquals("",first.getString("teamRunId"));assertEquals("new-run",first.getString("parentCoordinationScopeId"));assertEquals(1,pool.getJSONArray("reservations").length());assertEquals(4,TeamParentBudget.remaining(pool,"modelRequests"));assertThrows(SecurityException.class,()->TeamParentBudget.reserve(pool,binding().put("parentCoordinationScopeId","other-run"),"parent_coordination","call-original",1,0));assertThrows(SecurityException.class,()->TeamParentBudget.reserve(pool,binding().put("teamRunId","real-team-1"),"parent_coordination","call-original",1,0));}
    @Test public void projectCeilingIsNotARefillAndUnknownLateUsageRemainsCharged()throws Exception{JSONObject pool=TeamParentBudget.create("parent","new-run",1,2,source());JSONObject row=TeamParentBudget.reserve(pool,binding(),"parent_coordination","first",1,0);JSONObject site=new JSONObject().put("fixture",true);row.put("nativeCallSite",site);TeamParentBudget.startInferenceExact(pool,"parent","new-run","@parent",site,"call");TeamParentBudget.finishInference(pool,"call",new JSONObject().put("outcome","CANCELLED").put("usage",new JSONObject().put("reported",false)));assertEquals(0,TeamParentBudget.remaining(pool,"modelRequests"));assertEquals("unknown",row.getString("state"));assertThrows(IllegalStateException.class,()->TeamParentBudget.reserve(pool,binding(),"parent_coordination","second",1,0));assertEquals(1,pool.getInt("modelRequestLimit"));assertEquals(128,TeamParentBudget.modelCeiling(pool));assertEquals(128,TeamParentBudget.toolCeiling(pool));}
    @Test public void onlyNativeRecordedContinuationCanUseRemainingAndOldReservationNeverChangesRun()throws Exception {
        JSONObject pool=TeamParentBudget.create("parent","new-run",3,4,source()),old=TeamParentBudget.reserve(pool,binding(),"parent_coordination","old-original-call",1,0);old.put("state","unknown");String original=TeamWorkFiles.canonical(old);
        JSONObject next=binding().put("childRunId","next-run").put("childEpoch",3).put("nativeRoundContinuationDigest","b".repeat(64));
        assertThrows(SecurityException.class,()->TeamParentBudget.reserve(pool,next,"parent_coordination","next-call",1,0));assertEquals(1,pool.getJSONArray("reservations").length());
        pool.getJSONObject("budgetSource").put("ownerContinuations",new JSONArray().put(new JSONObject().put("taskId","parent").put("scopeId","new-run").put("toRunId","next-run").put("toEpoch",3).put("reviewDigest","b".repeat(64)).put("newBudgetUnits",0)));
        assertThrows(SecurityException.class,()->TeamParentBudget.reserve(pool,new JSONObject(next.toString()).put("childEpoch",4),"parent_coordination","wrong-epoch",1,0));
        assertThrows(SecurityException.class,()->TeamParentBudget.reserve(pool,next,"parent_coordination","old-original-call",1,0));
        JSONObject admitted=TeamParentBudget.reserve(pool,next,"parent_coordination","next-call",1,0);assertSame(admitted,TeamParentBudget.reserve(pool,next,"parent_coordination","next-call",1,0));assertEquals(original,TeamWorkFiles.canonical(old));assertEquals(3,pool.getInt("modelRequestLimit"));assertEquals(1,TeamParentBudget.remaining(pool,"modelRequests"));assertEquals(2,pool.getJSONArray("reservations").length());
        assertThrows(SecurityException.class,()->TeamParentBudget.reserve(pool,new JSONObject(next.toString()).put("nativeRoundContinuationDigest","c".repeat(64)),"parent_coordination","wrong-proof",1,0));
    }

}
